window.__PHD.push("n Informatics\uff09\", \"background\": null, \"chinese_or_csc\": null, \"graduation_year\": 2014}], \"total_estimate\": \"\u5728\u8bfb 3 / \u5df2\u6bd5\u4e1a 9\uff08\u4e3b\u9875\u5217\u8868\uff09\", \"student_pattern_zh\": \"HCI \u5b9e\u9a8c\u578b\u4e3a\u4e3b\uff1a\u65b0\u4ea4\u4e92\u6280\u672f\uff08\u7b14\u3001\u624b\u90e8\u8ffd\u8e2a AR\u3001AR \u7f51\u9875\uff09+ \u53d7\u63a7\u5b9e\u9a8c\uff1b\u65e9\u671f\u591a\u4e3a\u53ef\u89c6\u5316\u3002\", \"design_background_ok_zh\": \"\u672a\u89c1\u660e\u786e\u8bbe\u8ba1/\u827a\u672f\u80cc\u666f\u5b66\u751f\u8bc1\u636e\uff1b\u591a\u4e3a\u8ba1\u7b97\u673a\u80cc\u666f\uff08\u672a\u9010\u4e00\u6838\u5b9e\uff09\u3002\", \"chinese_students_zh\": \"Mengfei Gao \u4e3a\u4e2d\u6587\u59d3\u540d\u62fc\u97f3\uff0c\u6765\u6e90\u672a\u6807\u56fd\u7c4d\uff0c\u4e0d\u6807 CSC\u3002\", \"implication_zh\": \"\u53ef\u5f15\u7528 Dupr\u00e9 \u7684\u7eaf\u624b\u90e8\u8ffd\u8e2a AR \u8f93\u5165\u4f5c\u5207\u5165\uff1b\u4f46\u672c\u5c97\u4e3a\u5bfc\u822a\u8bfe\u9898\u4e14 2026 \u5e74\u5185\u5165\u804c\uff0c\u66f4\u9002\u5408\u95ee 2027 \u79cb\u5b63\u673a\u4f1a\u3002\", \"sources\": [\"https://pages.saclay.inria.fr/emmanuel.pietriga/\"], \"searched\": [\"Pietriga \u4e2a\u4eba\u4e3b\u9875\u5b66\u751f\u5217\u8868\", \"ILDA \u51fa\u7248\u7269\u9875\"]}, \"title_zh\": \"Inria \u9ad8\u7ea7\u7814\u7a76\u5458\uff08Directeur de Recherche\uff09\uff1bILDA \u56e2\u961f\u8d1f\u8d23\u4eba\", \"unit_zh\": \"ILDA \u56e2\u961f\uff0cInria \u8428\u514b\u96f7\u4e2d\u5fc3 / LISN\uff0c\u5df4\u9ece-\u8428\u514b\u96f7\u5927\u5b66\", \"email_hook_zh\": \"\u60a8\u4ec5\u51ed\u624b\u90e8\u8ffd\u8e2a\u7684 AR \u8f93\u5165\u7814\u7a76\uff08TriPad\u3001Hand-Bound Pads\uff09\u662f\u6211\u6240\u77e5\u4e0e\u6211\u57fa\u4e8e\u6d4f\u89c8\u5668\u7684 MediaPipe \u9057\u4ea7\u88c5\u7f6e\u6700\u63a5\u8fd1\u7684\u7814\u7a76\u3002\", \"csc_status_zh\": \"\u672a\u77e5\"}, {\"name\": \"Dr Alistair Brown\", \"school_en\": \"Durham University\", \"school_zh\": \"\u675c\u4f26\u5927\u5b66\", \"country\": \"\", \"title\": \"Associate Professor (Teaching) in Digital Humanities and Modern Literature\", \"unit\": \"Department of English Studies\", \"homepage\": \"https://www.durham.ac.uk/staff/alistair-brown/\", \"email\": \"alistair.brown@durham.ac.uk\", \"relevance\": 6, \"claim\": \"English Studies \u7684\u6570\u5b57\u4eba\u6587/VR \u5b66\u8005\uff0c\u4e3b\u6301 \u2018Theatre in the Round\u2019\uff08360 \u89c6\u9891+VR\uff09\u4e0e \u2018AI Enhanced VR Audiobooks\u2019\uff1b\u53ef\u4f5c\u4e3a Transformative Humanities \u7684 A&H \u4e3b\u5bfc\u5bfc\u5e08\uff0c\u914d\u8003\u53e4\u7cfb Paola Di Giuseppantonio Di Franco \u5f62\u6210\u8de8\u4e24\u9662\u7cfb\u56e2\u961f\u3002\", \"evidence_homepage\": \"https://www.durham.ac.uk/staff/alistair-brown/\", \"evidence_papers\": [{\"title\": \"Theatre in the round: a study of the effectiveness of 360-degree video and VR to address critical questions in the teaching and learning of drama\", \"year\": 2024, \"venue\": \"International Journal of Performance Arts and Digital Media 20(3)\", \"url\": \"https://doi.org/10.1080/14794713.2024.2434760\", \"link_to_user\": \"\u2018critically embodied spectatorship\u2019 \u6982\u5ff5\u53ef\u7528\u4e8e\u535a\u7269\u9986\u89c2\u4f17\u5728\u624b\u52bf-\u5149\u53d9\u4e8b\u4e2d\u7684\u5177\u8eab\u89c2\u770b\", \"title_zh\": \"\u5706\u5f62\u5267\u573a\uff1a360 \u5ea6\u89c6\u9891\u4e0e VR \u5728\u5e94\u5bf9\u620f\u5267\u6559\u5b66\u5173\u952e\u95ee\u9898\u4e2d\u7684\u6709\u6548\u6027\u7814\u7a76\"}], \"evidence_projects_funding\": \"PI\uff1aTheatre in the Round\uff082022\u201323\uff09\uff1bPI\uff1aAI Enhanced VR Audiobooks\uff08Durham \u5185\u90e8\u8d44\u52a9\uff0c2024\u2013\uff09\u3002\", \"fit_to_user\": \"\u53d9\u4e8b + \u6c89\u6d78 + \u5177\u8eab\u89c2\u770b\uff0c\u4e0e\u2018\u53d9\u4e8b\u7167\u660e\u2019\u548c\u535a\u7269\u9986\u4f53\u9a8c\u76f8\u901a\uff1b\u4eba\u6587\u4e3b\u5bfc\u6ee1\u8db3 TH \u89c4\u5219\u3002\", \"counterargument_risk\": \"\u6559\u5b66\u5e8f\u5217\uff08Teaching\uff09\u526f\u6559\u6388\uff0c\u80fd\u5426\u62c5\u4efb\u535a\u58eb\u4e3b\u5bfc\u5e08\u9700\u786e\u8ba4\uff1b\u65b9\u5411\u504f\u6587\u5b66/\u620f\u5267\uff0c\u975e\u9057\u4ea7\u6216\u7167\u660e\u3002\", \"email_hook\": \"Your idea of 'critically embodied spectatorship' in 360/VR drama is the lens I would like to apply to museum visitors whose gestures trigger narrative light.\", \"sources\": [\"https://www.durham.ac.uk/staff/alistair-brown/\", \"https://durham-repository.worktribe.com/person/210956/dr-alistair-brown\", \"https://orcid.org/0000-0003-1406-0875\"], \"verified\": true, \"csc_note\": \"Transformative Humanities\uff08\u56fd\u9645 2 \u4e2a\u540d\u989d\uff09\uff1bDurham-CSC 25 \u4e2a\u540d\u989d\u3002\", \"matched_keywords\": [\"digital humanities\", \"virtual reality\", \"360 video\", \"narrative\", \"embodied spectatorship\"], \"csc_status\": \"active\uff082027 \u5165\u5b66\u622a\u6b62\u5df2\u89c1\uff1a2027-01-16\uff09\", \"in_user_csc_list\": false, \"email_draft\": {\"to\": \"alistair.brown@durham.ac.uk\", \"subject\": \"Transformative Humanities PhD (2027): embodied spectatorship, gesture and light in museum heritage\", \"body\": \"Dear Dr Brown,\\n\\nI am planning to apply for a Durham PhD Studentship in Transformative Humanities (October 2027) and would be grateful to know whether you might lead a supervisory team. In 'Theatre in the round' you propose 'critically embodied spectatorship' for 360/VR drama. I would like to carry that idea into museums: what happens to a visitor's interpretation when their own gestures trigger light and narrative around a heritage object?\\n\\nI direct the Digital Intangible Cultural Heritage Design and Production teaching and research office at Quanzhou Huaguang College, where I teach 3D character design and digital sculpting, guide students' 3D content production, and lead a VR collaborative lighting design project (JAT251371). Before that I was a lighting hardware product manager at OSRAM/LEDVANCE (nine product series, about 100 SKUs, around US$8M in sales, including light-distribution and ambience simulation for Zayed International Airport) and at LEEDARSON, where my user and market research fed smart-lighting lines that sold over US$30M; I also interned in IoT product management at TCL.\\n\\nMy most relevant prototype is Stone Reveal (Dunhuang project on my homepage): four Dunhuang Buddha figures rebuilt as GPU particle clouds in Three.js, driven by MediaPipe hand tracking in the browser, so visitors brush away the 'dust' with a fingertip and bring their palms together to reveal the gilded figure. The project would combine Research through Design with qualitative audience study, which I hope suits the Digital Humanities theme. Because the scheme needs two departments, I would also hope to approach Dr Paola Di Giuseppantonio Di Franco in Archaeology, whose digital heritage work complements yours.\\n\\nTo be candid: my degrees are in design (MFA, Jiangsu University), I have no first-author peer-reviewed paper yet, and my IELTS result is expected by March 2027. I bring working prototypes, a granted invention patent, industry-grade user research and a teaching team for field studies, and I would turn them into rigorous studies early.\\n\\nWould you be willing to discuss a two-page proposal before the 15 January deadline?\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College\\nhanleizeng@gmail.com | https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aBrown 2024 IJPADM \u8bba\u6587\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u2460Brown \u4e3a Teaching \u5e8f\u5217\uff0c\u5148\u95ee\u5176\u80fd\u5426\u62c5\u4efb\u4e3b\u5bfc\uff1b\u2461\u662f\u5426\u540c\u65f6\u8054\u7cfb Paola\uff08\u5df2\u5728\u5e93\uff09\uff1b\u2462\u6b64\u4fe1\u4e0d\u63d0 CSC\uff08TH \u4e3a\u5e26\u85aa\u5c97\uff09\u3002\", \"subject_zh\": \"Transformative Humanities \u535a\u58eb\uff082027\uff09\uff1a\u535a\u7269\u9986\u9057\u4ea7\u4e2d\u7684\u5177\u8eab\u89c2\u770b\u3001\u624b\u52bf\u4e0e\u5149\", \"body_zh\": \"\u5c0a\u656c\u7684 Brown \u535a\u58eb\uff1a\\n\\n\u6211\u8ba1\u5212\u7533\u8bf7\u675c\u4f26\u5927\u5b66 Transformative Humanities \u535a\u58eb\u5168\u989d\u5956\u5b66\u91d1\uff082027 \u5e74 10 \u6708\u5165\u5b66\uff09\uff0c\u60f3\u8bf7\u6559\u60a8\u662f\u5426\u53ef\u80fd\u9886\u8854\u6211\u7684\u5bfc\u5e08\u56e2\u961f\u3002\u60a8\u5728\u300aTheatre in the round\u300b\uff08\u73af\u5f62\u5267\u573a\uff09\u4e00\u6587\u4e2d\u4e3a 360/VR \u620f\u5267\u63d0\u51fa\u4e86\u201ccritically embodied spectatorship\u201d\uff08\u6279\u5224\u6027\u5177\u8eab\u89c2\u770b\uff09\u3002\u6211\u5e0c\u671b\u628a\u8fd9\u4e00\u6982\u5ff5\u5e26\u8fdb\u535a\u7269\u9986\uff1a\u5f53\u89c2\u4f17\u81ea\u5df1\u7684\u624b\u52bf\u89e6\u53d1\u56f4\u7ed5\u9057\u4ea7\u6587\u7269\u7684\u5149\u4e0e\u53d9\u4e8b\u65f6\uff0c\u4ed6\u4eec\u7684\u7406\u89e3\u4f1a\u53d1\u751f\u4ec0\u4e48\u53d8\u5316\uff1f\\n\\n\u6211\u73b0\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\uff08Quanzhou Huaguang College\uff09\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u4e0e\u6570\u5b57\u96d5\u523b\uff0c\u6307\u5bfc\u5b66\u751f\u7684 3D \u5185\u5bb9\u751f\u4ea7\uff0c\u5e76\u4e3b\u6301 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u5728 OSRAM/LEDVANCE \u4efb\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff08\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\u3001\u7ea6 100 \u4e2a SKU\u3001\u7d2f\u8ba1\u9500\u552e\u7ea6 800 \u4e07\u7f8e\u5143\uff0c\u5305\u62ec\u4e3a\u624e\u8036\u5fb7\u56fd\u9645\u673a\u573a\uff08Zayed International Airport\uff09\u9879\u76ee\u505a\u914d\u5149\u5206\u6790\u4e0e\u6c1b\u56f4\u6a21\u62df\uff09\uff0c\u5728\u7acb\u8fbe\u4fe1\uff08LEEDARSON\uff09\u4efb\u4ea7\u54c1\u7ecf\u7406\u671f\u95f4\uff0c\u6211\u7684\u7528\u6237\u4e0e\u5e02\u573a\u7814\u7a76\u652f\u6491\u4e86\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u7684\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\uff1b\u6211\u8fd8\u66fe\u5728 TCL \u62c5\u4efb IoT \u4ea7\u54c1\u7ecf\u7406\u5b9e\u4e60\u751f\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u89c1\u6211\u4e3b\u9875\u7684\u6566\u714c\u9879\u76ee\uff09\uff1a\u7528 Three.js \u628a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u91cd\u5efa\u4e3a GPU \u7c92\u5b50\u4e91\uff0c\u5e76\u5728\u6d4f\u89c8\u5668\u4e2d\u7531 MediaPipe \u624b\u90e8\u8ffd\u8e2a\u9a71\u52a8\u2014\u2014\u89c2\u4f17\u7528\u6307\u5c16\u62c2\u53bb\u201c\u5c18\u571f\u201d\uff0c\u53cc\u638c\u5408\u5341\u5373\u663e\u73b0\u938f\u91d1\u4f5b\u50cf\u3002\u8be5\u9879\u76ee\u5c06\u7ed3\u5408\u8bbe\u8ba1\u7814\u7a76\u6cd5\uff08RtD\uff09\u4e0e\u5b9a\u6027\u89c2\u4f17\u7814\u7a76\uff0c\u6211\u5e0c\u671b\u5b83\u5951\u5408\u6570\u5b57\u4eba\u6587\u4e3b\u9898\u3002\u7531\u4e8e\u8be5\u8ba1\u5212\u8981\u6c42\u4e24\u4e2a\u9662\u7cfb\u8054\u5408\u6307\u5bfc\uff0c\u6211\u4e5f\u5e0c\u671b\u8054\u7cfb\u8003\u53e4\u7cfb\u7684 Paola Di Giuseppantonio Di Franco \u535a\u58eb\uff0c\u5979\u7684\u6570\u5b57\u9057\u4ea7\u7814\u7a76\u4e0e\u60a8\u7684\u65b9\u5411\u4e92\u8865\u3002\\n\\n\u5766\u767d\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u90fd\u5728\u8bbe\u8ba1\u9886\u57df\uff08\u6c5f\u82cf\u5927\u5b66\u827a\u672f\u7855\u58eb MFA\uff09\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u7684\u540c\u884c\u8bc4\u5ba1\u8bba\u6587\uff0c\u96c5\u601d\u6210\u7ee9\u9884\u8ba1 2027 \u5e74 3 \u6708\u524d\u51fa\u5206\u3002\u6211\u80fd\u5e26\u6765\u7684\u662f\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5df2\u6388\u6743\u7684\u53d1\u660e\u4e13\u5229\u3001\u5de5\u4e1a\u7ea7\u7684\u7528\u6237\u7814\u7a76\u7ecf\u9a8c\uff0c\u4ee5\u53ca\u53ef\u652f\u6491\u7530\u91ce\u7814\u7a76\u7684\u6559\u5b66\u56e2\u961f\uff0c\u6211\u4f1a\u5c3d\u65e9\u628a\u8fd9\u4e9b\u8f6c\u5316\u4e3a\u4e25\u8c28\u7684\u7814\u7a76\u3002\\n\\n\u60a8\u662f\u5426\u613f\u610f\u5728 1 \u6708 15 \u65e5\u622a\u6b62\u524d\u8ba8\u8bba\u4e00\u4efd\u4e24\u9875\u7814\u7a76\u8ba1\u5212\uff1f\\n\\n\u6b64\u81f4\\n\u656c\u793c\\n\u66fe\u97e9\u64c2\uff08Hanlei (Eli) Zeng\uff09\\n\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\nhanleizeng@gmail.com | https://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": false, \"students\": [], \"total_estimate\": \"\u672a\u77e5\", \"student_pattern_zh\": \"\", \"design_background_ok_zh\": \"\", \"chinese_students_zh\": \"\", \"implication_zh\": \"Teaching \u5e8f\u5217\uff0c\u53ef\u80fd\u65e0\u535a\u58eb\u6307\u5bfc\u8bb0\u5f55\uff1b\u9700\u5728\u4fe1\u4e2d\u8be2\u95ee\u5176\u80fd\u5426\u62c5\u4efb\u4e3b\u5bfc\u6216\u4e0e Paola \u5171\u540c\u6307\u5bfc\u3002\", \"sources\": [\"https://www.durham.ac.uk/staff/alistair-brown/\"], \"searched\": [\"Durham \u5458\u5de5\u4e3b\u9875\", \"Durham Research Online \u4e2a\u4eba\u9875\"]}, \"title_zh\": \"\u6570\u5b57\u4eba\u6587\u4e0e\u73b0\u4ee3\u6587\u5b66\u526f\u6559\u6388\uff08\u6559\u5b66\u5c97\uff09\", \"unit_zh\": \"\u82f1\u8bed\u7814\u7a76\u7cfb\", \"evidence_projects_funding_zh\": \"PI\uff1aTheatre in the Round\uff082022\u201323\uff09\uff1bPI\uff1aAI \u589e\u5f3a VR \u6709\u58f0\u4e66\uff08\u675c\u4f26\u5927\u5b66\u5185\u90e8\u8d44\u52a9\uff0c2024\u2013\uff09\u3002\", \"email_hook_zh\": \"\u60a8\u5728 360/VR \u620f\u5267\u4e2d\u63d0\u51fa\u7684\u201c\u6279\u5224\u6027\u5177\u8eab\u89c2\u770b\u201d\u7406\u5ff5\uff0c\u6b63\u662f\u6211\u60f3\u7528\u6765\u5ba1\u89c6\u90a3\u4e9b\u4ee5\u624b\u52bf\u89e6\u53d1\u53d9\u4e8b\u5149\u6548\u7684\u535a\u7269\u9986\u89c2\u4f17\u7684\u89c6\u89d2\u3002\", \"csc_note_zh\": \"\u53d8\u9769\u6027\u4eba\u6587\u5b66\u79d1\uff08\u56fd\u9645\u751f 2 \u4e2a\u540d\u989d\uff09\uff1b\u675c\u4f26\u5927\u5b66-CSC 25 \u4e2a\u540d\u989d\u3002\"}, {\"name\": \"Daniel Bisig\", \"school_en\": \"Zurich University of the Arts (ZHdK) \u2013 ICST\", \"school_zh\": \"\u82cf\u9ece\u4e16\u827a\u672f\u5927\u5b66\", \"country\": \"\", \"title\": \"Dr., Senior Researcher (ICST since 2006; Immersive Arts Space since 2020)\", \"unit\": \"Institute for Computer Music and Sound Technology (ICST), Zurich University of the Arts\", \"homepage\": \"https://www.zhdk.ch/en/research/icst\", \"email\": null, \"relevance\": 6, \"claim\": \"Bisig \u662f ICST \u8d44\u6df1\u7814\u7a76\u5458\u3001Animated Objects \u9879\u76ee\u4e2d\u8d1f\u8d23'\u821e\u8e48\u52a8\u4f5c\u5206\u6790'\u7684\u7814\u7a76\u7ebf\uff0c\u505a\u751f\u6210\u827a\u672f\u3001\u52a8\u6355\u4e0e AI \u821e\u8005\u4ea4\u4e92\uff1b\u53ef\u4f5c\u4e3a\u8be5\u5c97\u4f4d\u7684\u5171\u540c\u6307\u5bfc/\u65e5\u5e38\u5bfc\u5e08\uff0c\u4f46\u975e\u6b63\u5f0f\u535a\u5bfc\u3002\", \"evidence_homepage\": \"https://www.zhdk.ch/en/research/icst\", \"evidence_papers\": [{\"title\": \"Motionforms. A Kinetic Light and Sound Installation\", \"year\": 2025, \"venue\": \"xCoAx 2025 (13th Conference on Computation, Communication, Aesthetics & X), 60\u201364, with P. Kocher\", \"url\": \"https://www.zhdk.ch/en/research/icst/publications-chronological-since-1985-1024\", \"link_to_user\": \"\u52a8\u6001\u5149+\u58f0\u88c5\u7f6e \u2192 \u4e0e\u7528\u6237'\u53ef\u7f16\u7a0b\u5b9e\u4f53\u5149'\u65b9\u5411\u6700\u8d34\u8fd1\", \"title_zh\": \"Motionforms\uff1a\u52a8\u6001\u5149\u4e0e\u58f0\u97f3\u88c5\u7f6e\"}, {\"title\": \"Puppeteering AI \u2013 Interactive Control of an Artificial Dancer\", \"year\": 2022, \"venue\": \"Generative AI and HCI Workshop, CHI 2022 (with E. Wegner)\", \"url\": \"https://wp.coventry.domains/e2create/publications/\", \"link_to_user\": \"\u7528\u8eab\u4f53\u59ff\u6001\u5b9e\u65f6\u64cd\u63a7\u751f\u6210\u5f0f\u89d2\u8272 \u2192 \u4e0e\u7528\u6237\u624b\u52bf\u63a7\u5236\u7c92\u5b50\u5f62\u4f53\u540c\u6784\", \"title_zh\": \"\u64cd\u63a7 AI\u2014\u2014\u4eba\u5de5\u821e\u8005\u7684\u4ea4\u4e92\u63a7\u5236\"}, {\"title\": \"Expressive Aliens \u2013 Laban Effort Factors for Non-anthropomorphic Morphologies\", \"year\": 2022, \"venue\": \"EvoMUSART 2022, LNCS 13221, 36\u201351\", \"url\": \"https://doi.org/10.1007/978-3-031-03789-4_3\", \"link_to_user\": \"\u628a\u52a8\u4f5c\u8d28\u611f\u6620\u5c04\u5230\u975e\u4eba\u5f62\u5f62\u4f53 \u2192 \u53ef\u501f\u9274\u5230'\u6587\u7269\u7c92\u5b50\u4f53'\u7684\u8fd0\u52a8\u8868\u8fbe\", \"title_zh\": \"\u5bcc\u6709\u8868\u73b0\u529b\u7684\u5916\u661f\u751f\u7269\u2014\u2014\u62c9\u73ed\u529b\u6548\u56e0\u7d20\u5728\u975e\u62df\u4eba\u5f62\u6001\u4e2d\u7684\u5e94\u7528\"}], \"evidence_projects_funding\": \"Animated Objects\uff08SNSF\uff09\u4e2d\u8d1f\u8d23\u821e\u8e48\u52a8\u4f5c\u5206\u6790\u7814\u7a76\u7ebf\uff1bICST AIR \u9a7b\u7559 'Dance and Generative AI'\uff08PEMIDA \u7cfb\u7edf\uff09\uff1b\u66fe\u83b7 Marie Curie Fellowship\uff08Coventry \u821e\u8e48\u7814\u7a76\u4e2d\u5fc3\u52a9\u7406\u6559\u6388 2020\u20132022\uff09\uff1b'Immersive Lab' \u624b\u52bf\u89e6\u63a7\u58f0\u50cf\u7a7a\u95f4\u3002\", \"fit_to_user\": \"\u624b\u52bf/\u8eab\u4f53\u9a71\u52a8\u7684\u751f\u6210\u89c6\u89c9\u3001\u7c92\u5b50\u7fa4\uff08flocking agents\uff09\u3001\u52a8\u6001\u5149\u88c5\u7f6e\uff0c\u4e0e\u7528\u6237 GPU \u7c92\u5b50+\u624b\u52bf\u4ea4\u4e92\u6280\u672f\u6808\u6700\u63a5\u8fd1\u3002\", \"counterargument_risk\": \"\u804c\u79f0\u4e3a senior researcher\uff08\u975e\u6559\u6388\uff09\uff0c\u4e0d\u80fd\u5355\u72ec\u4f5c\u4e3a\u4e3b\u5bfc\u5e08\uff1b\u65e0\u72ec\u7acb\u62db\u751f\u8d44\u52a9\uff0c\u5165\u53e3\u4ecd\u662f Gottfried \u7684 SNSF \u5c97\u4f4d\uff1b\u5b98\u65b9\u4e2a\u4eba\u9875\u4e3a JS \u9875\u9762\u65e0\u6cd5\u8bfb\u53d6\u90ae\u7bb1\u3002\", \"email_hook\": \"Your Motionforms kinetic light installation and the flocking-agent work sit very close to my particle-based, gesture-driven heritage prototypes.\", \"sources\": [\"https://www.zhdk.ch/en/research/icst\", \"https://orcid.org/0000-0002-3538-2008\", \"https://www.zhdk.ch/en/research/icst/publications-chronological-since-1985-1024\", \"https://www.musikzeitung.ch/news/2026/04/nationalfonds-foerdert-zhdk-projekt\", \"https://zurichmade.zhdk.ch/refresh-2/talks/daniel-bisig\"], \"verified\": true, \"csc_note\": \"\u975e CSC \u7ebf\uff1a\u8be5\u5c97\u4f4d\u4e3a SNSF \u5168\u989d\u8d44\u52a9 4 \u5e74\u535a\u58eb\u804c\u4f4d\uff08\u6309 SNSF \u6807\u51c6\u53d1\u85aa\uff09\uff0c\u622a\u6b62 2026-11-01\uff0c11/16 \u5f53\u5468\u9762\u8bd5\uff0c\u535a\u58eb\u5b66\u4f4d\u7ecf HfMT Hamburg\uff08Ligeti Center\uff09\u6388\u4e88\uff0c2027 \u6625\u5165\u804c\u3002\", \"matched_keywords\": [\"gesture interaction\", \"generative art / particles\", \"motion capture\", \"kinetic light\"], \"csc_status\": \"paused_or_stopped\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": null, \"subject\": \"Question about the Animated Objects PhD: gesture-driven particles and kinetic light\", \"body\": \"Dear Dr Bisig,\\n\\nYour Motionforms kinetic light and sound installation, and your work on flocking agents and Puppeteering AI, sit very close to the prototypes I build. I direct a teaching and research office for digital intangible cultural heritage at Quanzhou Huaguang College, and I am considering the PhD position in the ICST project \\\"Animated Objects and Moving Sound Sources\\\", where I understand you lead the movement-analysis strand.\\n\\nSince November 2025 I have led that office, teaching 3D character design and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran 9 product series at OSRAM/LEDVANCE (~100 SKUs, ~US$8M sales), including light-distribution analysis for Abu Dhabi's Zayed airport project, and led user research at LEEDARSON for smart-lighting lines selling over US$30M.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as GPU particle clouds in Three.js, with MediaPipe hand tracking in the browser, so visitors brush away the \\\"dust\\\" with a fingertip and hold their palms together to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nIn the project I would be most interested in the human-scale study: tracking performers' and visitors' gestures and mapping them to moving light, particles and sound, and asking how such mappings carry cultural meaning.\\n\\nTo be direct: my degrees are in design, not music or computer science, and I have no first-author paper yet. My strengths are working prototypes and a practice-based method.\\n\\nWould you be willing to tell me whether this profile could fit the project team? I would be glad to send a two-page outline.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aMotionforms \u52a8\u6001\u5149\u88c5\u7f6e + \u7c92\u5b50\u7fa4/AI \u821e\u8005\u624b\u52bf\u63a7\u5236\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u90ae\u7bb1\u672a\u5728\u5b98\u65b9\u53ef\u8bfb\u9875\u9762\u516c\u5f00\uff08\u8bba\u6587\u7f72\u540d\u7528\u8fc7 daniel.bisig@zhdk.ch\uff0c\u9700\u81ea\u884c\u6838\u5b9e\u540e\u518d\u586b\uff09\uff1b\u4ed6\u975e\u6b63\u5f0f\u535a\u5bfc\uff0c\u5efa\u8bae\u5148\u8054\u7cfb Gottfried\uff0c\u518d\u6284\u9001/\u53e6\u53d1 Bisig\u3002\", \"subject_zh\": \"\u5173\u4e8e Animated Objects \u535a\u58eb\u804c\u4f4d\u7684\u54a8\u8be2\uff1a\u624b\u52bf\u9a71\u52a8\u7684\u7c92\u5b50\u4e0e\u52a8\u6001\u5149\", \"body_zh\": \"\u5c0a\u656c\u7684 Bisig \u535a\u58eb\uff1a\\n\\n\u60a8\u7684 Motionforms \u52a8\u6001\u5149\u4e0e\u58f0\u97f3\u88c5\u7f6e\uff0c\u4ee5\u53ca\u60a8\u5728\u7fa4\u96c6\u667a\u80fd\u4f53\uff08flocking agents\uff09\u548c Puppeteering AI \u65b9\u9762\u7684\u5de5\u4f5c\uff0c\u90fd\u4e0e\u6211\u6784\u5efa\u7684\u539f\u578b\u975e\u5e38\u63a5\u8fd1\u3002\u6211\u5728\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u4e3b\u6301\u4e00\u4e2a\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u6559\u7814\u5ba4\uff0c\u6b63\u5728\u8003\u8651\u7533\u8bf7 ICST \u9879\u76ee\u201cAnimated Objects and Moving Sound Sources\u201d\uff08\u300a\u52a8\u753b\u7269\u4f53\u4e0e\u79fb\u52a8\u58f0\u6e90\u300b\uff09\u4e2d\u7684\u535a\u58eb\u804c\u4f4d\uff0c\u636e\u6211\u4e86\u89e3\u60a8\u8d1f\u8d23\u5176\u4e2d\u7684\u52a8\u4f5c\u5206\u6790\u65b9\u5411\u3002\\n\\n\u81ea2025\u5e7411\u6708\u8d77\uff0c\u6211\u4e3b\u6301\u8be5\u6559\u7814\u5ba4\uff0c\u4e3b\u8bb23D\u89d2\u8272\u8bbe\u8ba1\uff0c\u5e76\u4e3b\u6301VR\u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u4f5c\u4e3a\u7167\u660e\u884c\u4e1a\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff0c\u6211\u5728 OSRAM/LEDVANCE \u8d1f\u8d239\u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6100\u4e2aSKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6800\u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5e76\u5728\u7acb\u8fbe\u4fe1\uff08LEEDARSON\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc73000\u4e07\u7f8e\u5143\u3002\\n\\n\u6211\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u7a9f\u663e\u50cf\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u6211\u5728 Three.js \u4e2d\u5c06\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u91cd\u5efa\u4e3aGPU\u7c92\u5b50\u4e91\uff0c\u5e76\u5728\u6d4f\u89c8\u5668\u4e2d\u4f7f\u7528 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u8ba9\u89c2\u4f17\u7528\u6307\u5c16\u62c2\u53bb\u201c\u5c18\u57c3\u201d\uff0c\u518d\u53cc\u638c\u5408\u5341\uff0c\u663e\u73b0\u51fa\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u8be5\u9879\u76ee\u4e2d\uff0c\u6211\u6700\u611f\u5174\u8da3\u7684\u662f\u4eba\u4f53\u5c3a\u5ea6\u7684\u7814\u7a76\uff1a\u8ffd\u8e2a\u8868\u6f14\u8005\u548c\u89c2\u4f17\u7684\u624b\u52bf\uff0c\u5c06\u5176\u6620\u5c04\u4e3a\u79fb\u52a8\u7684\u5149\u3001\u7c92\u5b50\u548c\u58f0\u97f3\uff0c\u5e76\u63a2\u8ba8\u8fd9\u4e9b\u6620\u5c04\u5982\u4f55\u627f\u8f7d\u6587\u5316\u610f\u4e49\u3002\\n\\n\u5766\u767d\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u4e13\u4e1a\uff0c\u800c\u975e\u97f3\u4e50\u6216\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\u3002\u6211\u7684\u4f18\u52bf\u662f\u53ef\u8fd0\u884c\u7684\u539f\u578b\u548c\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u3002\\n\\n\u8bf7\u95ee\u60a8\u80fd\u5426\u544a\u8bc9\u6211\uff0c\u8fd9\u6837\u7684\u80cc\u666f\u662f\u5426\u9002\u5408\u8be5\u9879\u76ee\u56e2\u961f\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u63d0\u7eb2\u3002\\n\\n\u6b64\u81f4\u656c\u793c\uff0c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": false, \"students\": [], \"total_estimate\": \"\u672a\u67e5\u5230\u5176\u4f5c\u4e3a\u4e3b\u5bfc\u5e08\u7684\u535a\u58eb\u751f\uff1b\u66fe\u5217\u4e3az-node\uff08ZHdK\u2013Plymouth\uff09\u535a\u58eb\u9879\u76ee\u7684second supervisor\", \"student_pattern_zh\": \"\u65e0\u53ef\u6838\u5b9e\u5b66\u751f\u540d\u5355\u3002\u5176\u7814\u7a76\u4e3a\u821e\u8e48\u52a8\u4f5c\u5206\u6790\u3001AI\u4e0e\u58f0\u97f3/\u97f3\u4e50\u8ba1\u7b97\uff0c\u5e76\u53c2\u4e0eGottfried\u7684Animated Objects\u9879\u76ee\uff08\u52a8\u4f5c\u5206\u6790\uff09\u3002\", \"design_background_ok_zh\": \"\u65e0\u5b66\u751f\u6570\u636e\uff1b\u6240\u5728ICST\u4e0ez-node\u9879\u76ee\u9762\u5411\u827a\u672f\u5bb6\uff0c\u80cc\u666f\u53cb\u597d\u5ea6\u63a8\u65ad\u8f83\u9ad8\uff08\u63a8\u65ad\uff09\u3002\", \"chinese_students_zh\": \"\u672a\u53d1\u73b0\u3002\", \"implication_zh\": \"Bisig\u662f\u9ad8\u7ea7\u7814\u7a76\u5458\uff08Dr.\uff0c\u975e\u6559\u6388\uff09\uff0c\u5728\u745e\u58eb\u5e94\u7528\u827a\u672f\u5927\u5b66\u4f53\u7cfb\u4e2d\u65e0\u72ec\u7acb\u6388\u4e88\u535a\u58eb\u8d44\u683c\uff0c\u9002\u5408\u4f5c\u4e3a\u9879\u76ee\u5185\u5408\u4f5c\u8005/\u7b2c\u4e8c\u5bfc\u5e08\uff1b\u82e5\u7533\u8bf7ICST\uff0c\u5e94\u4ee5Gottfried\u7684SNSF\u535a\u58eb\u5c97\u4e3a\u5165\u53e3\uff0cBisig\u8d1f\u8d23\u52a8\u4f5c/\u821e\u8e48\u5206\u6790\u6a21\u5757\u2014\u2014\u4e0e\u7528\u6237\u624b\u52bf/\u8eab\u4f53\u4ea4\u4e92\u65b9\u5411\u5951\u5408\u3002\", \"sources\": [\"https://www.z-node.net/pages/supervisors.html\", \"https://www.musikzeitung.ch/news/2026/04/nationalfonds-foerdert-zhdk-projekt\", \"https://www.zhdk.ch/en/research/icst\"], \"searched\": [\"ZHdK ICST\u4eba\u5458\u9875\", \"z-node\u535a\u58eb\u9879\u76ee\u5bfc\u5e08\u5217\u8868\", \"Schweizer Musikzeitung\u65b0\u95fb\", \"ResearchGate\", \"web\u641c\u7d22 Bisig PhD supervisor\"]}, \"title_zh\": \"\u535a\u58eb\uff0c\u9ad8\u7ea7\u7814\u7a76\u5458\uff082006 \u5e74\u8d77\u5728 ICST\uff1b2020 \u5e74\u8d77\u5728\u6c89\u6d78\u827a\u672f\u7a7a\u95f4\uff09\", \"unit_zh\": \"\u8ba1\u7b97\u673a\u97f3\u4e50\u4e0e\u58f0\u97f3\u6280\u672f\u7814\u7a76\u6240\uff08ICST\uff09\uff0c\u82cf\u9ece\u4e16\u827a\u672f\u5927\u5b66\", \"email_hook_zh\": \"Your Motionforms kinetic light installation and the flocking-agent work sit very close to my particle-based, gesture-driven heritage prototypes.\uff08\u60a8\u7684 Motionforms \u52a8\u6001\u5149\u88c5\u7f6e\u4e0e\u7fa4\u96c6\u667a\u80fd\u4f53\u4f5c\u54c1\uff0c\u4e0e\u6211\u57fa\u4e8e\u7c92\u5b50\u3001\u624b\u52bf\u9a71\u52a8\u7684\u9057\u4ea7\u539f\u578b\u975e\u5e38\u63a5\u8fd1\u3002\uff09\", \"csc_status_zh\": \"\u5df2\u6682\u505c\u6216\u505c\u6b62\"}, {\"name\": \"Anna Xamb\u00f3 Sed\u00f3\", \"school_en\": \"Queen Mary University of London\", \"school_zh\": \"\u4f26\u6566\u739b\u4e3d\u5973\u738b\u5927\u5b66\", \"country\": \"\", \"title\": \"Dr., Senior Lecturer in Sound and Music Computing; lead, Computational Sonic Arts Lab\", \"unit\": \"Centre for Digital Music (C4DM), School of Electronic Engineering and Computer Science\", \"homepage\": \"https://www.qmul.ac.uk/eecs/people/profiles/annaxambosedo.html\", \"email\": \"a.xambosedo@qmul.ac.uk\", \"relevance\": 6, \"claim\": \"Xamb\u00f3 \u505a HCI/NIME \u4e2d\u7684\u5177\u8eab\u4e0e\u6709\u5f62\u4ea4\u4e92\u3001\u624b\u52bf\u8bc6\u522b\u4e0e\u53c2\u4e0e\u5f0f\u8868\u6f14\uff0c\u5176\u5b9e\u9a8c\u5ba4\u8fd1\u5e74\u5df2\u53d1\u5e03 CSC \u8d44\u52a9\u535a\u58eb\u5c97\uff0c\u662f QMUL\u2013CSC \u901a\u9053\u91cc\u63a5\u53d7'\u4ea4\u4e92\u8bbe\u8ba1+\u521b\u4f5c\u5b9e\u8df5'\u578b\u7533\u8bf7\u8005\u7684\u53ef\u884c\u5bfc\u5e08\u3002\", \"evidence_homepage\": \"https://www.qmul.ac.uk/eecs/people/profiles/annaxambosedo.html\", \"evidence_papers\": [{\"title\": \"Towards an integrated methodological framework for understanding embodiment in HCI\", \"year\": 2014, \"venue\": \"CHI EA 2014, 1411\u20131416 (with C. Jewitt)\", \"url\": \"https://doi.org/10.1145/2559206.2581276\", \"link_to_user\": \"HCI \u4e2d'\u5177\u8eab'\u7684\u7814\u7a76\u65b9\u6cd5\u6846\u67b6 \u2192 \u7528\u6237'\u624b\u52bf\u4f5c\u4e3a\u6587\u5316\u7406\u89e3'\u7684\u65b9\u6cd5\u8bba\u57fa\u7840\", \"title_zh\": \"\u8fc8\u5411\u7406\u89e3\u4eba\u673a\u4ea4\u4e92\u4e2d\u5177\u8eab\u6027\u7684\u7efc\u5408\u65b9\u6cd5\u6846\u67b6\"}, {\"title\": \"Experience and Ownership with a Tangible Computational Music Installation for Informal Learning\", \"year\": 2017, \"venue\": \"TEI 2017, 351\u2013360\", \"url\": \"https://doi.org/10.1145/3024969.3024988\", \"link_to_user\": \"\u975e\u6b63\u5f0f\u5b66\u4e60\u573a\u666f\u7684\u6709\u5f62\u4ea4\u4e92\u88c5\u7f6e\u8bc4\u4f30 \u2192 \u53ef\u8fc1\u79fb\u5230\u535a\u7269\u9986\u624b\u52bf\u88c5\u7f6e\u8bc4\u4f30\", \"title_zh\": \"\u9762\u5411\u975e\u6b63\u5f0f\u5b66\u4e60\u7684\u53ef\u89e6\u8ba1\u7b97\u97f3\u4e50\u88c5\u7f6e\u4e2d\u7684\u4f53\u9a8c\u4e0e\u5f52\u5c5e\u611f\"}, {\"title\": \"Exploring gestural affordances in audio latent space navigation\", \"year\": 2025, \"venue\": \"Frontiers in Computer Science 7 (with S. Zheng, N. Bryan-Kinns)\", \"url\": \"https://doi.org/10.3389/fcomp.2025.1575202\", \"link_to_user\": \"\u624b\u52bf\u5728\u751f\u6210\u5f0f\u7a7a\u95f4\u4e2d\u5bfc\u822a \u2192 \u4e0e\u7528\u6237\u624b\u52bf\u64cd\u63a7\u7c92\u5b50\u5f62\u4f53\u7684\u4ea4\u4e92\u6620\u5c04\u95ee\u9898\u540c\u6784\", \"title_zh\": \"\u63a2\u7d22\u97f3\u9891\u6f5c\u7a7a\u95f4\u5bfc\u822a\u4e2d\u7684\u624b\u52bf\u53ef\u4f9b\u6027\"}], \"evidence_projects_funding\": \"AHRC 'Sensing the Forest'\uff08PI\uff0c2023\u20132025\uff09\uff1bEPSRC HDI Network Plus 'MIRLCAuto'\uff08PI\uff09\uff1bComputational Sonic Arts Lab \u66fe\u53d1\u5e03 'PhD Studentship Funded by China Scholarship Council'\uff1bC4DM Studios \u6280\u672f\u8054\u5408\u4e3b\u4efb\u3002\", \"fit_to_user\": \"\u5177\u8eab/\u6709\u5f62\u4ea4\u4e92\u3001\u624b\u52bf\u8bc6\u522b\u3001Web \u5b9e\u65f6\u4ea4\u4e92\u7cfb\u7edf\uff08web audio/JS\uff09\u4e0e\u7528\u6237\u6d4f\u89c8\u5668\u7aef Three.js+MediaPipe \u505a\u6cd5\u4e00\u81f4\uff1b\u5b9e\u9a8c\u5ba4\u719f\u6089 CSC \u6d41\u7a0b\u3002\", \"counterargument_risk\": \"\u6838\u5fc3\u5bf9\u8c61\u662f\u58f0\u97f3/\u97f3\u4e50\u800c\u975e\u89c6\u89c9/\u7167\u660e/\u6587\u7269\uff1b\u7528\u6237\u65e0\u97f3\u4e50\u80cc\u666f\uff1b\u9700\u628a\u8bfe\u9898\u6539\u5199\u4e3a'\u591a\u611f\u5b98\uff08\u5149+\u58f0\uff09\u5177\u8eab\u4ea4\u4e92'\u624d\u53ef\u80fd\u5339\u914d\u3002\", \"email_hook\": \"Your work on gestural affordances and tangible installations for informal learning maps closely onto my browser-based gesture interfaces for heritage objects.\", \"sources\": [\"https://www.qmul.ac.uk/eecs/people/profiles/annaxambosedo.html\", \"https://researchpublications.qmul.ac.uk/publications/staff/41762.html\", \"https://annaxambo.me/about\", \"https://scholar.google.com/citations?hl=en&user=yi3WXM8AAAAJ\", \"https://compsonicartslab.github.io/\"], \"verified\": true, \"csc_note\": \"QMUL\u2013CSC \u8054\u5408\u5956\u5b66\u91d1 active\uff1a\u7ea6 60 \u540d/\u5e74\uff0c2027 \u622a\u6b62 2027-01-27 16:00 GMT\uff0c\u82f1\u8bed\u7b49\u6750\u6599\u7ea6 3 \u6708\u4e2d\u65ec\u8865\u4ea4\uff082026 \u4e3a 3/17\uff09\uff1b\u9700\u5148\u62ff QMUL offer\u3002\", \"matched_keywords\": [\"embodied interaction\", \"tangible interaction\", \"gesture\", \"HCI\", \"practice-based\"], \"csc_status\": \"active\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"a.xambosedo@qmul.ac.uk\", \"subject\": \"PhD enquiry (QMUL\u2013CSC 2027): multisensory gesture interaction for cultural heritage\", \"body\": \"Dear Dr Xamb\u00f3,\\n\\nYour CHI paper with Carey Jewitt on a methodological framework for embodiment in HCI, and your recent Frontiers article on gestural affordances, address the question at the centre of my practice: how a gesture becomes meaningful, not just an input. I direct a teaching and research office for digital intangible cultural heritage at Quanzhou Huaguang College, and I would like to apply for a PhD at C4DM through the QMUL\u2013CSC scholarship for 2027.\\n\\nSince November 2025 I have led that office, teaching 3D character design and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran 9 product series at OSRAM/LEDVANCE (~100 SKUs, ~US$8M sales), including light-distribution analysis for Abu Dhabi's Zayed airport project, and led user research at LEEDARSON for smart-lighting lines selling over US$30M. My office also provides study participants.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as GPU particle clouds in Three.js, with MediaPipe hand tracking in the browser, so visitors brush away the \\\"dust\\\" with a fingertip and hold their palms together to reveal the gilded figure. A companion project does the same for Chinese bronzes. Like much of your work, it runs entirely in the browser.\\n\\nFor a PhD I would like to study multisensory, gesture-driven interaction with heritage objects \u2014 how mappings from hand movement to light, particles and sound shape engagement and learning in museums \u2014 drawing on your TEI work on tangible installations for informal learning.\\n\\nTo be direct: my degrees are in design, not computer science or music, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nWould you be open to discussing whether this could fit your lab? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aXamb\u00f3 & Jewitt 2014 \u5177\u8eab\u65b9\u6cd5\u6846\u67b6 + 2025 \u624b\u52bf\u53ef\u4f9b\u6027 + TEI 2017 \u975e\u6b63\u5f0f\u5b66\u4e60\u88c5\u7f6e\uff1b\u5f3a\u8c03\u6d4f\u89c8\u5668\u7aef\u5b9e\u73b0\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u8bfe\u9898\u9700\u52a0\u5165'\u58f0\u97f3'\u7ef4\u5ea6\u624d\u5bf9\u53e3\uff1b\u5979\u5b9e\u9a8c\u5ba4 2027 \u5e74\u662f\u5426\u8fd8\u6709 CSC \u540d\u989d\uff1bQMUL\u2013CSC 1/27 \u622a\u6b62\u4e0e\u82f1\u8bed\u6210\u7ee9\u65f6\u95f4\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff08QMUL\u2013CSC 2027\uff09\uff1a\u9762\u5411\u6587\u5316\u9057\u4ea7\u7684\u591a\u611f\u5b98\u624b\u52bf\u4ea4\u4e92\", \"body_zh\": \"\u5c0a\u656c\u7684 Xamb\u00f3 \u535a\u58eb\uff1a\\n\\n\u60a8\u4e0e Carey Jewitt \u5408\u4f5c\u3001\u53d1\u8868\u4e8eCHI\u7684\u5173\u4e8e\u4eba\u673a\u4ea4\u4e92\u4e2d\u5177\u8eab\u6027\u7684\u65b9\u6cd5\u8bba\u6846\u67b6\u8bba\u6587\uff0c\u4ee5\u53ca\u60a8\u8fd1\u671f\u53d1\u8868\u5728 Frontiers \u4e0a\u5173\u4e8e\u624b\u52bf\u53ef\u4f9b\u6027\u7684\u6587\u7ae0\uff0c\u89e6\u53ca\u6211\u5b9e\u8df5\u7684\u6838\u5fc3\u95ee\u9898\uff1a\u624b\u52bf\u5982\u4f55\u6210\u4e3a\u6709\u610f\u4e49\u7684\u884c\u4e3a\uff0c\u800c\u4e0d\u4ec5\u4ec5\u662f\u4e00\u79cd\u8f93\u5165\u3002\u6211\u5728\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u4e3b\u6301\u4e00\u4e2a\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u6559\u7814\u5ba4\uff0c\u5e0c\u671b\u901a\u8fc72027\u5e74 QMUL\u2013CSC \u5956\u5b66\u91d1\u7533\u8bf7 C4DM \u7684\u535a\u58eb\u3002\\n\\n\u81ea2025\u5e7411\u6708\u8d77\uff0c\u6211\u4e3b\u6301\u8be5\u6559\u7814\u5ba4\uff0c\u4e3b\u8bb23D\u89d2\u8272\u8bbe\u8ba1\uff0c\u5e76\u4e3b\u6301VR\u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u4f5c\u4e3a\u7167\u660e\u884c\u4e1a\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff0c\u6211\u5728 OSRAM/LEDVANCE \u8d1f\u8d239\u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6100\u4e2aSKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6800\u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5e76\u5728\u7acb\u8fbe\u4fe1\uff08LEEDARSON\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc73000\u4e07\u7f8e\u5143\u3002\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u80fd\u63d0\u4f9b\u7814\u7a76\u53c2\u4e0e\u8005\u3002\\n\\n\u6211\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u7a9f\u663e\u50cf\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u6211\u5728 Three.js \u4e2d\u5c06\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u91cd\u5efa\u4e3aGPU\u7c92\u5b50\u4e91\uff0c\u5e76\u5728\u6d4f\u89c8\u5668\u4e2d\u4f7f\u7528 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u8ba9\u89c2\u4f17\u7528\u6307\u5c16\u62c2\u53bb\u201c\u5c18\u57c3\u201d\uff0c\u518d\u53cc\u638c\u5408\u5341\uff0c\u663e\u73b0\u51fa\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\u548c\u60a8\u7684\u8bb8\u591a\u4f5c\u54c1\u4e00\u6837\uff0c\u5b83\u5b8c\u5168\u5728\u6d4f\u89c8\u5668\u4e2d\u8fd0\u884c\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u4e0e\u9057\u4ea7\u6587\u7269\u7684\u591a\u611f\u5b98\u3001\u624b\u52bf\u9a71\u52a8\u4ea4\u4e92\u2014\u2014\u4ece\u624b\u90e8\u52a8\u4f5c\u5230\u5149\u3001\u7c92\u5b50\u548c\u58f0\u97f3\u7684\u6620\u5c04\u5982\u4f55\u5f71\u54cd\u535a\u7269\u9986\u4e2d\u7684\u53c2\u4e0e\u5ea6\u548c\u5b66\u4e60\u2014\u2014\u5e76\u501f\u9274\u60a8\u5728TEI\u4e0a\u5173\u4e8e\u9762\u5411\u975e\u6b63\u5f0f\u5b66\u4e60\u7684\u53ef\u89e6\u88c5\u7f6e\u7684\u7814\u7a76\u3002\\n\\n\u5766\u767d\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u662f\u8bbe\u8ba1\u4e13\u4e1a\uff0c\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\u6216\u97f3\u4e50\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u4f5c\u4e3a\u5408\u8457\u8005\u53d1\u8868\u8fc7\u4e24\u7bc7MR\u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5df2\u6388\u6743\u7684\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u79cd\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u2014\u2014\u6211\u4f1a\u5c3d\u65e9\u5c06\u5176\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u6210\u679c\u3002\\n\\n\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u63a2\u8ba8\u8fd9\u4e00\u65b9\u5411\u80fd\u5426\u5951\u5408\u60a8\u7684\u5b9e\u9a8c\u5ba4\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\u656c\u793c\uff0c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Shuoyang Zheng\", \"status\": \"current\", \"start_year\": 2023, \"graduation_year\": null, \"thesis_title\": \"(lab page: PhD 2023\u2013present) gestural affordances in audio latent space navigation / AI music interfaces\", \"topic_zh\": \"AI \u97f3\u9891\u6a21\u578b\u6f5c\u7a7a\u95f4\u4e2d\u7684\u624b\u52bf\u53ef\u4f9b\u6027\u4e0e\u6f14\u594f\u6280\u6cd5\uff08\u5e73\u677f\u6570\u5b57\u4e50\u5668\uff09\", \"url\": \"https://compsonicartslab.github.io/people\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"co_supervisors\": \"Nick Bryan-Kinns\uff08AIM/C4DM\uff09\", \"co_supervisors_zh\": \"Nick Bryan-Kinns\uff08AIM/C4DM\uff09\"}, {\"name\": \"Qiaoxi Zhang\", \"status\": \"current\", \"start_year\": 2023, \"graduation_year\": null, \"thesis_title\": \"(lab page: PhD 2023\u2013present) contour-conditioned symbolic music generation\", \"topic_zh\": \"\u57fa\u4e8e\u8f6e\u5ed3\u8349\u56fe\u63a7\u5236\u7684\u7b26\u53f7\u97f3\u4e50\u751f\u6210\uff08TENOR 2025 \u4e8e\u4e2d\u592e\u97f3\u4e50\u5b66\u9662\u53d1\u8868\uff09\", \"url\": \"https://compsonicartslab.github.io/people\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"co_supervisors\": \"Mathieu Barthet\uff08AIM/C4DM\uff09\", \"co_supervisors_zh\": \"Mathieu Barthet\uff08AIM/C4DM\uff09\"}, {\"name\": \"Nicol\u00e1s Ant\u00f3nio Garc\u00eda-Peguinho\", \"status\": \"current\", \"start_year\": 2025, \"graduation_year\": null, \"thesis_title\": \"(lab page) few-shot bird vocalisation detection with causal explanations (Sensing the Forest)\", \"topic_zh\": \"\u5c11\u6837\u672c\u9e1f\u9e23\u68c0\u6d4b\u4e0e\u56e0\u679c\u89e3\u91ca\uff08\u68ee\u6797\u58f0\u666f\u9879\u76ee\uff09\", \"url\": \"https://compsonicartslab.github.io/people\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"co_supervisors\": \"Fabrizio Smeraldi\", \"co_supervisors_zh\": \"Fabrizio Smeraldi\"}, {\"name\": \"Lianganzi Wang\", \"status\": \"current\", \"start_year\": 2025, \"graduation_year\": null, \"thesis_title\": \"(lab page) real-time stable mapping from multimodal sensing to interpretable timbre axes\", \"topic_zh\": \"\u591a\u6a21\u6001\u4f20\u611f\u5230\u53ef\u89e3\u91ca\u97f3\u8272\u8f74\u7684\u5b9e\u65f6\u6620\u5c04\uff08\u4f20\u611f/\u8eab\u4f53\u2192\u58f0\u97f3\uff09\", \"url\": \"https://compsonicartslab.github.io/people\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"co_supervisors\": \"Iran Roman\", \"co_supervisors_zh\": \"Iran Roman\"}, {\"name\": \"Lina Bautista\", \"status\": \"current\", \"start_year\": 2025, \"graduation_year\": null, \"thesis_title\": \"(lab page: PhD 2025\u2013present; topic not stated)\", \"topic_zh\": \"\u8bfe\u9898\u672a\u6ce8\u660e\uff08\u4e0e UOC \u5408\u4f5c\u6307\u5bfc\uff09\", \"url\": \"https://compsonicartslab.github.io/people\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"co_supervisors\": \"Enric Mor (UOC)\", \"co_supervisors_zh\": \"Enric Mor (UOC)\"}, {\"name\": \"Merlin Goldman\", \"status\": \"current\", \"start_year\": 2026, \"graduation_year\": null, \"thesis_title\": \"(lab page: PhD 2026\u2013present; topic not stated)\", \"topic_zh\": \"\u8bfe\u9898\u672a\u6ce8\u660e\", \"url\": \"https://compsonicartslab.github.io/people\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"co_supervisors\": \"Mark Sandler\", \"co_supervisors_zh\": \"Mark Sandler\"}, {\"name\": \"Amias Hanley\", \"status\": \"current\", \"start_year\": 2026, \"graduation_year\": null, \"thesis_title\": \"(lab page: PhD 2026\u2013present, Geography/C4DM; topic not stated)\", \"topic_zh\": \"\u5730\u7406\u5b66/C4DM \u4ea4\u53c9\uff0c\u8bfe\u9898\u672a\u6ce8\u660e\", \"url\": \"https://compsonicartslab.github.io/people\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"co_supervisors\": \"Kathryn Yusoff\", \"co_supervisors_zh\": \"Kathryn Yusoff\"}], \"total_estimate\": \"\u5728\u8bfb 7\uff082023 \u8d77 2 \u4eba\uff0c2025 \u8d77 3 \u4eba\uff0c2026 \u8d77 2 \u4eba\uff09\uff0c\u5747\u4e3a\u8054\u5408\u6307\u5bfc\uff1b\u6682\u65e0 QMUL \u6bd5\u4e1a\u535a\u58eb\uff082023 \u5e74\u624d\u5165\u804c QMUL\uff09\", \"student_pattern_zh\": \"Computational Sonic Arts Lab\uff08C4DM\uff09\uff1aAI \u97f3\u4e50\u754c\u9762\u4e0e\u6f5c\u7a7a\u95f4\u624b\u52bf\u6f14\u594f\u3001\u8f6e\u5ed3\u8349\u56fe\u63a7\u5236\u7684\u97f3\u4e50\u751f\u6210\u3001\u591a\u6a21\u6001\u4f20\u611f\u2192\u97f3\u8272\u6620\u5c04\u3001\u68ee\u6797\u58f0\u666f\u4e0e\u9e1f\u9e23\u68c0\u6d4b\uff08Sensing the Forest\uff09\u3001LLM \u53ef\u542c\u5316\u3002\u5b9e\u8df5\u578b+\u5b9e\u9a8c\u578b\u5e76\u91cd\uff08NIME/live coding \u793e\u533a\uff09\uff0c\u5e38\u6709\u6f14\u51fa/\u88c5\u7f6e\u4ea7\u51fa\u3002\", \"design_background_ok_zh\": \"Xamb\u00f3 \u672c\u4eba\u6709\u52a8\u753b/\u591a\u5a92\u4f53\u8bbe\u8ba1\u4e0e\u4eba\u7c7b\u5b66\u80cc\u666f\u5e76\u505a\u8fc7 10 \u5e74\u4ea4\u4e92\u8bbe\u8ba1\u5e08\uff08about \u9875\uff09\uff0c\u5b9e\u9a8c\u5ba4\u5f3a\u8c03\u521b\u4f5c\u5b9e\u8df5\uff1b\u5b66\u751f\u80cc\u666f\u672a\u9010\u4e00\u516c\u5f00\u3002\", \"chinese_students_zh\": \"\u6709\uff1aShuoyang Zheng\u3001Qiaoxi Zhang\u3001Lianganzi Wang\uff08\u59d3\u540d\u63a8\u6d4b\u4e3a\u4e2d\u56fd\u5b66\u751f\uff0c\u8d44\u91d1\u672a\u516c\u5f00\uff09\u3002\u5173\u952e\uff1a2025-11 \u5b9e\u9a8c\u5ba4\u516c\u5f00 CSC \u8d44\u52a9\u535a\u58eb\u5c97\u4f4d 'Sonification techniques for understanding hidden processes of LLMs'\uff08\u4e3b\u5bfc Xamb\u00f3\uff0c\u526f\u5bfc Saitis\uff0c\u622a\u6b62 2026-01-28\uff09\uff0c\u8bf4\u660e\u5176\u4e3b\u52a8\u63a5\u6536 CSC \u5b66\u751f\u3002\", \"implication_zh\": \"\u5207\u5165\u70b9\uff1aZheng \u7684'\u6f5c\u7a7a\u95f4\u624b\u52bf\u53ef\u4f9b\u6027'\u548c Wang \u7684'\u591a\u6a21\u6001\u4f20\u611f\u2192\u97f3\u8272'\u4e0e\u7528\u6237\u7684\u624b\u52bf\u9a71\u52a8/TouchDesigner/MediaPipe \u80fd\u529b\u9ad8\u5ea6\u5bf9\u63a5\uff1b\u53e6\u6709 'Collaborative Motion-Based Hybrid Live Coding'\uff08\u52a8\u4f5c/\u89e6\u89c9\uff09\u5c97\u4f4d\u601d\u8def\uff08\u4f46\u8be5\u5c97\u9650\u82f1\u56fd\u672c\u571f\u5f31\u52bf\u7fa4\u4f53\uff09\u3002\u53ef\u6309'\u624b\u52bf\u2192\u58f0\u5149\u53d9\u4e8b\uff08\u53d9\u4e8b\u7167\u660e+\u58f0\u97f3\uff09\u7528\u4e8e\u975e\u9057\u5c55\u6f14'\u63d0\u6848\uff0c\u5e76\u660e\u786e\u8d70 CSC-QMUL \u901a\u9053\u3002\u98ce\u9669\uff1a\u58f0\u97f3/\u97f3\u4e50\u8ba1\u7b97\u5bfc\u5411\u5f3a\uff0c\u9700\u8981\u7f16\u7a0b\u4e0e\u97f3\u9891\u57fa\u7840\uff1b\u5b9e\u9a8c\u5ba4\u5c1a\u65e0\u6bd5\u4e1a\u751f\uff0c\u6307\u5bfc\u7ecf\u9a8c\u4ee5\u8054\u5408\u6307\u5bfc\u4e3a\u4e3b\u3002\", \"sources\": [\"https://compsonicartslab.github.io/people\", \"https://compsonicartslab.github.io/News/2025/11/Exciting-PhD-Studentship-Open-in-Our-Lab-Funded-by-China-Scholarship-Council\", \"https://compsonicartslab.github.io/News/2025/12/PhD-Opportunity-on-Collaborative-Motion-Based-Hybrid-Live-Coding\", \"https://annaxambo.me/about\"], \"searched\": [\"\u5b9e\u9a8c\u5ba4 People \u9875\u4e0e\u65b0\u95fb\u9875\", \"\u4e2a\u4eba\u4e3b\u9875 about\", \"QMUL \u4e2a\u4eba\u9875\uff08batch \u6765\u6e90\uff09\"]}, \"title_zh\": \"\u535a\u58eb\uff0c\u58f0\u97f3\u4e0e\u97f3\u4e50\u8ba1\u7b97\u9ad8\u7ea7\u8bb2\u5e08\uff1b\u8ba1\u7b97\u58f0\u97f3\u827a\u672f\u5b9e\u9a8c\u5ba4\u8d1f\u8d23\u4eba\", \"unit_zh\": \"\u6570\u5b57\u97f3\u4e50\u4e2d\u5fc3\uff08C4DM\uff09\uff0c\u7535\u5b50\u5de5\u7a0b\u4e0e\u8ba1\u7b97\u673a\u79d1\u5b66\u5b66\u9662\", \"evidence_projects_funding_zh\": \"AHRC\u201c\u611f\u77e5\u68ee\u6797\u201d\uff08PI\uff0c2023\u20132025\uff09\uff1bEPSRC HDI Network Plus\u201cMIRLCAuto\u201d\uff08PI\uff09\uff1b\u8ba1\u7b97\u58f0\u97f3\u827a\u672f\u5b9e\u9a8c\u5ba4\u66fe\u53d1\u5e03\u201c\u56fd\u5bb6\u7559\u5b66\u57fa\u91d1\u59d4\u8d44\u52a9\u535a\u58eb\u5c97\u201d\uff1bC4DM \u5de5\u4f5c\u5ba4\u6280\u672f\u8054\u5408\u4e3b\u4efb\u3002\", \"email_hook_zh\": \"Your work on gestural affordances and tangible installations for informal learning maps closely onto my browser-based gesture interfaces for heritage objects.\uff08\u60a8\u5173\u4e8e\u624b\u52bf\u53ef\u4f9b\u6027\u4e0e\u975e\u6b63\u5f0f\u5b66\u4e60\u53ef\u89e6\u88c5\u7f6e\u7684\u7814\u7a76\uff0c\u4e0e\u6211\u9762\u5411\u6587\u7269\u7684\u6d4f\u89c8\u5668\u624b\u52bf\u754c\u9762\u9ad8\u5ea6\u5bf9\u5e94\u3002\uff09\", \"csc_status_zh\": \"\u6d3b\u8dc3\"}, {\"name\": \"Damon Daylamani-Zad\", \"school_en\": \"Brunel University of London\", \"school_zh\": \"\u4f26\u6566\u5e03\u9c81\u5185\u5c14\u5927\u5b66\", \"country\": \"\", \"title\": \"Dr., Senior Lecturer in Digital Media (Creative Computing \u2013 AI and Games); Director of Education, Brunel Design School; Head of Creative Computing Research Group\", \"unit\": \"Digital Media, Brunel Design School, College of Engineering, Design and Physical Sciences\", \"homepage\": \"https://www.brunel.ac.uk/people/damon-daylamani-zad\", \"email\": \"damon.daylamani-zad@brunel.ac.uk\", \"relevance\": 6, \"claim\": \"Daylamani-Zad \u662f\u8bbe\u8ba1\u5b66\u9662\u6570\u5b57\u5a92\u4f53\u65b9\u5411\u8d1f\u8d23\u4eba\uff0c\u4e0e Dima \u5408\u4f5c MR \u9057\u4ea7\u8868\u6f14\u4e0e MR \u5f00\u53d1\u6d41\u7a0b\u4e2d\u7684 AI \u5de5\u5177\uff0c\u5e76\u8fd0\u8425 'Mixed Reality for Social Impact'\uff0c\u53ef\u4f5c\u4e3a Garaj/Dima \u7684\u6280\u672f\u578b\u8054\u5408\u5bfc\u5e08\u3002\", \"evidence_homepage\": \"https://www.brunel.ac.uk/people/damon-daylamani-zad\", \"evidence_papers\": [{\"title\": \"Acting on the Edge: Developing Mixed Reality Heritage Performance through Real-Time 3D and Virtual Production Technologies\", \"year\": 2026, \"venue\": \"ACM Journal on Computing and Cultural Heritage (with M. Dima, V. Lympouridis)\", \"url\": \"https://doi.org/10.1145/3846377\", \"link_to_user\": \"\u5b9e\u65f6 3D MR \u9057\u4ea7\u4f53\u9a8c \u2192 \u7528\u6237\u5b9e\u65f6\u7c92\u5b50\u9057\u4ea7\u539f\u578b\", \"title_zh\": \"\u8fb9\u7f18\u8868\u6f14\uff1a\u501f\u52a9\u5b9e\u65f6\u4e09\u7ef4\u4e0e\u865a\u62df\u5236\u4f5c\u6280\u672f\u53d1\u5c55\u6df7\u5408\u73b0\u5b9e\u9057\u4ea7\u8868\u6f14\"}, {\"title\": \"Intelligent Immersion: The current landscape of AI tools in the Mixed Reality development pipeline for creative experiences\", \"year\": 2024, \"venue\": \"Revista de la Asociaci\u00f3n Espa\u00f1ola de Investigaci\u00f3n de la Comunicaci\u00f3n 11 (with M. Dima)\", \"url\": \"https://doi.org/10.24137/raeic.11.e.1\", \"link_to_user\": \"MR \u521b\u4f5c\u6d41\u7a0b\u4e2d\u7684 AI \u5de5\u5177 \u2192 \u7528\u6237 3D \u6a21\u578b\u2192\u70b9\u4e91/\u7c92\u5b50\u7684\u5185\u5bb9\u751f\u4ea7\u6d41\u7a0b\", \"title_zh\": \"\u667a\u80fd\u6c89\u6d78\uff1a\u6df7\u5408\u73b0\u5b9e\u521b\u610f\u4f53\u9a8c\u5f00\u53d1\u6d41\u7a0b\u4e2d AI \u5de5\u5177\u7684\u73b0\u72b6\"}, {\"title\": \"Heuristics for AI-Driven Graphical Asset Generation Tools in Game Design and Development Pipelines: A User-Centered Approach\", \"year\": 2026, \"venue\": \"International Journal of Human-Computer Interaction (with K. Fukaya, H. Agius)\", \"url\": \"https://doi.org/10.1080/10447318.2026.2632170\", \"link_to_user\": \"\u4ee5\u7528\u6237\u4e3a\u4e2d\u5fc3\u8bc4\u4f30\u751f\u6210\u5f0f\u8d44\u4ea7\u5de5\u5177 \u2192 \u975e\u9057\u6570\u5b57\u5185\u5bb9\u751f\u4ea7\u6559\u5b66\", \"title_zh\": \"\u6e38\u620f\u8bbe\u8ba1\u4e0e\u5f00\u53d1\u6d41\u7a0b\u4e2d AI \u9a71\u52a8\u56fe\u5f62\u8d44\u4ea7\u751f\u6210\u5de5\u5177\u7684\u542f\u53d1\u5f0f\u51c6\u5219\uff1a\u4ee5\u7528\u6237\u4e3a\u4e2d\u5fc3\u7684\u65b9\u6cd5\"}], \"evidence_projects_funding\": \"Creative Computing Research Group \u8d1f\u8d23\u4eba\uff1b'Mixed Reality for Social Impact'\uff08mxr4impact.com\uff09\u4e0e 'Games for Life, Health and Accessibility' \u9879\u76ee\uff1b\u5b98\u65b9\u9875\u8bbe PhD supervision \u680f\u76ee\u3002\", \"fit_to_user\": \"\u8bbe\u8ba1\u5b66\u9662\u5185\u7684 MR/\u6e38\u620f/\u521b\u610f\u8ba1\u7b97\u65b9\u5411\uff0c\u63a5\u53d7\u8bbe\u8ba1\u80cc\u666f\uff1b\u6280\u672f\u4fa7\u53ef\u8865\u8db3\u7528\u6237\u5b9e\u65f6\u56fe\u5f62\u4e0e\u7cfb\u7edf\u5b9e\u73b0\u3002\", \"counterargument_risk\": \"\u7814\u7a76\u91cd\u5fc3\u662f AI \u4e0e\u6e38\u620f\uff0c\u9057\u4ea7\u4ec5\u4e3a\u4e0e Dima \u7684\u5408\u4f5c\u7ebf\uff1b\u4e0d\u6d89\u53ca\u7167\u660e\uff1b\u4f5c\u4e3a\u4e3b\u5bfc\u5e08\u5bf9\u53e3\u5ea6\u4e00\u822c\uff0c\u66f4\u9002\u5408\u5f53\u7b2c\u4e8c\u5bfc\u5e08\u3002\", \"email_hook\": \"Your work with Dr Dima on real-time MR heritage performance and on AI tools in MR pipelines connects to how I turn 3D scans of artefacts into interactive particle experiences.\", \"sources\": [\"https://www.brunel.ac.uk/people/damon-daylamani-zad\", \"https://www.brunel.ac.uk/people/mariza-dima\", \"https://doi.org/10.1145/3846377\", \"https://mxr4impact.com/\"], \"verified\": true, \"csc_note\": \"Brunel\u2013CSC \u8054\u5408\u5956\u5b66\u91d1 2027/28\uff1a20 \u540d\uff0c\u622a\u6b62 2027-01-08 12:00 UK\uff0c\u7533\u8bf7\u65f6\u9009 CSC \u5e76\u586b\u610f\u5411\u5bfc\u5e08\uff1b2 \u6708\u5e95\u53d1 offer\u3002\", \"matched_keywords\": [\"MR/XR\", \"digital cultural heritage\", \"games\", \"creative computing\", \"HCI\"], \"csc_status\": \"active\", \"in_user_csc_list\": false, \"email_draft\": {\"to\": \"damon.daylamani-zad@brunel.ac.uk\", \"subject\": \"PhD enquiry (Brunel\u2013CSC 2027): real-time gesture-driven MR for cultural heritage\", \"body\": \"Dear Dr Daylamani-Zad,\\n\\nYour recent work with Dr Mariza Dima \u2014 \\\"Acting on the Edge\\\" on real-time mixed-reality heritage performance and \\\"Intelligent Immersion\\\" on AI tools in MR pipelines \u2014 connects directly to how I turn 3D scans of artefacts into interactive experiences. I direct a teaching and research office for digital intangible cultural heritage at Quanzhou Huaguang College, and I would like to apply for a PhD at the Brunel Design School through the Brunel\u2013CSC Joint Scholarship 2027/28.\\n\\nSince November 2025 I have led that office, teaching 3D character design and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran 9 product series at OSRAM/LEDVANCE (~100 SKUs, ~US$8M sales), including light-distribution analysis for Abu Dhabi's Zayed airport project, and led user research at LEEDARSON for smart-lighting lines selling over US$30M. My office also supplies heritage 3D data and students.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as GPU particle clouds in Three.js, with MediaPipe hand tracking in the browser, so visitors brush away the \\\"dust\\\" with a fingertip and hold their palms together to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven interaction and narrative lighting in real-time MR shape presence and cultural learning in museums, and how such experiences can be produced efficiently from heritage 3D data. I would see your expertise as the technical side of a supervisory team, possibly alongside Dr Dima or Professor Garaj.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent on an MR customisation method, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI understand the Brunel deadline is 8 January 2027. Would you be open to supervising or co-supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a\u4e0e Dima \u5408\u4f5c\u7684 MR \u9057\u4ea7\u8868\u6f14 + MR \u6d41\u7a0b AI \u5de5\u5177\uff0c\u5bf9\u4e0a\u7528\u6237'3D \u6a21\u578b\u2192\u7c92\u5b50'\u5185\u5bb9\u751f\u4ea7\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u4ed6\u66f4\u9002\u5408\u7b2c\u4e8c\u5bfc\u5e08\uff0c\u5efa\u8bae\u5148\u8054\u7cfb Garaj \u6216 Dima \u4f5c\u4e3a\u4e3b\u5bfc\u5e08\u518d\u63d0\u4ed6\uff1b\u67e5\u770b\u5176 PhD supervision \u9875\u662f\u5426\u5217\u51fa\u53ef\u6307\u5bfc\u9898\u76ee\uff1b1/8 \u622a\u6b62\u4e0e\u8bed\u8a00\u6210\u7ee9\u95ee\u9898\u540c Garaj\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff08Brunel\u2013CSC 2027\uff09\uff1a\u9762\u5411\u6587\u5316\u9057\u4ea7\u7684\u5b9e\u65f6\u624b\u52bf\u9a71\u52a8MR\", \"body_zh\": \"\u5c0a\u656c\u7684 Daylamani-Zad \u535a\u58eb\uff1a\\n\\n\u60a8\u8fd1\u671f\u4e0e Mariza Dima \u535a\u58eb\u5408\u4f5c\u7684\u7814\u7a76\u2014\u2014\u5173\u4e8e\u5b9e\u65f6\u6df7\u5408\u73b0\u5b9e\u9057\u4ea7\u8868\u6f14\u7684\u201cActing on the Edge\u201d\uff08\u300a\u5728\u8fb9\u7f18\u8868\u6f14\u300b\uff09\u4ee5\u53ca\u5173\u4e8eMR\u5236\u4f5c\u6d41\u7a0b\u4e2dAI\u5de5\u5177\u7684\u201cIntelligent Immersion\u201d\uff08\u300a\u667a\u80fd\u6c89\u6d78\u300b\uff09\u2014\u2014\u4e0e\u6211\u628a\u6587\u7269\u4e09\u7ef4\u626b\u63cf\u8f6c\u5316\u4e3a\u4ea4\u4e92\u4f53\u9a8c\u7684\u65b9\u5f0f\u76f4\u63a5\u76f8\u5173\u3002\u6211\u5728\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u4e3b\u6301\u4e00\u4e2a\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u6559\u7814\u5ba4\uff0c\u5e0c\u671b\u901a\u8fc72027/28\u5e74\u5ea6\u5e03\u9c81\u5185\u5c14\u2013CSC\u8054\u5408\u5956\u5b66\u91d1\u7533\u8bf7\u5e03\u9c81\u5185\u5c14\u8bbe\u8ba1\u5b66\u9662\u7684\u535a\u58eb\u3002\\n\\n\u81ea2025\u5e7411\u6708\u8d77\uff0c\u6211\u4e3b\u6301\u8be5\u6559\u7814\u5ba4\uff0c\u4e3b\u8bb23D\u89d2\u8272\u8bbe\u8ba1\uff0c\u5e76\u4e3b\u6301VR\u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u4f5c\u4e3a\u7167\u660e\u884c\u4e1a\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff0c\u6211\u5728 OSRAM/LEDVANCE \u8d1f\u8d239\u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6100\u4e2aSKU\uff0c\u7d2f\u8ba1\u9500\u552e\u7ea6800\u4e07\u7f8e\u5143\uff09\uff0c\u5176\u4e2d\u5305\u62ec\u963f\u5e03\u624e\u6bd4 Zayed \u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5e76\u5728\u7acb\u8fbe\u4fe1\uff08LEEDARSON\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u7d2f\u8ba1\u9500\u552e\u8d85\u8fc73000\u4e07\u7f8e\u5143\u3002\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u80fd\u63d0\u4f9b\u9057\u4ea7\u4e09\u7ef4\u6570\u636e\u548c\u5b66\u751f\u53c2\u4e0e\u3002\\n\\n\u6211\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u300a\u77f3\u7a9f\u663e\u50cf\u300b\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u6211\u5728 Three.js \u4e2d\u5c06\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u91cd\u5efa\u4e3aGPU\u7c92\u5b50\u4e91\uff0c\u5e76\u5728\u6d4f\u89c8\u5668\u4e2d\u4f7f\u7528 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u8ba9\u89c2\u4f17\u7528\u6307\u5c16\u62c2\u53bb\u201c\u5c18\u57c3\u201d\uff0c\u518d\u53cc\u638c\u5408\u5341\uff0c\u663e\u73b0\u51fa\u938f\u91d1\u4f5b\u8eab\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u4ee5\u540c\u6837\u65b9\u5f0f\u5448\u73b0\u4e2d\u56fd\u9752\u94dc\u5668\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u5b9e\u65f6MR\u4e2d\u7684\u624b\u52bf\u9a71\u52a8\u4ea4\u4e92\u548c\u53d9\u4e8b\u7167\u660e\u5982\u4f55\u5f71\u54cd\u535a\u7269\u9986\u4e2d\u7684\u4e34\u573a\u611f\u548c\u6587\u5316\u5b66\u4e60\uff0c\u4ee5\u53ca\u5982\u4f55\u4ece\u9057\u4ea7\u4e09\u7ef4\u6570\u636e\u9ad8\u6548\u5236\u4f5c\u6b64\u7c7b\u4f53\u9a8c\u3002\u6211\u5e0c\u671b\u60a8\u80fd\u4f5c\u4e3a\u5bfc\u5e08\u56e2\u961f\u4e2d\u7684\u6280\u672f\u65b9\u5bfc\u5e08\uff0c\u6216\u8bb8\u4e0e Dima \u535a\u58eb\u6216 Garaj \u6559\u6388\u5171\u540c\u6307\u5bfc\u3002\\n\\n\u5766\u767d\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u90fd\u662f\u8bbe\u8ba1\u4e13\u4e1a\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u4f5c\u4e3a\u5408\u8457\u8005\u53d1\u8868\u8fc7\u4e24\u7bc7MR\u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5df2\u6388\u6743\u7684MR\u5b9a\u5236\u65b9\u6cd5\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u79cd\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u2014\u2014\u6211\u4f1a\u5c3d\u65e9\u5c06\u5176\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u6210\u679c\u3002\\n\\n\u636e\u6211\u4e86\u89e3\uff0c\u5e03\u9c81\u5185\u5c14\u7684\u622a\u6b62\u65e5\u671f\u662f2027\u5e741\u67088\u65e5\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u6216\u8054\u5408\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\u656c\u793c\uff0c\\nHanlei (Eli) Zeng\uff08\u66fe\u97e9\u64c2\uff09\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Kaisei Fukaya\", \"status\": \"alumni\", \"graduation_year\": 2025, \"thesis_title\": \"User-centred artificial intelligence for game design and development with GAGeTx: Graphical Asset Generation and Transformation\", \"topic_zh\": \"\u4ee5\u7528\u6237\u4e3a\u4e2d\u5fc3\u7684 AI \u6e38\u620f\u7f8e\u672f\u8d44\u4ea7\u751f\u6210\u4e0e\u53d8\u6362\uff08GAGeTx\uff09\", \"url\": \"https://bura.brunel.ac.uk/handle/2438/30775\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"role\": \"\u4e3b\u5bfc\u5e08\uff0c\u4e0e Harry Agius \u5408\u5e26\uff1b\u65e9\u671f\u5408\u4f5c dyslexia \u591a\u611f\u5b98 3D \u73af\u5883\"}, {\"name\": \"Neil Alexander\", \"status\": \"alumni\", \"graduation_year\": 2025, \"thesis_title\": \"Developing decision-making skills and tactical awareness in rugby union players through user-centred serious games\", \"topic_zh\": \"\u7528\u4e25\u8083\u6e38\u620f\u8bad\u7ec3\u6a44\u6984\u7403\u8fd0\u52a8\u5458\u51b3\u7b56\u4e0e\u6218\u672f\u610f\u8bc6\", \"url\": \"https://bura.brunel.ac.uk/handle/2438/33439\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"role\": \"\u4e3b\u5bfc\u5e08\uff0c\u4e0e Marios Angelides \u5408\u5e26\"}, {\"name\": \"Habeebullah Yusuf\", \"status\": \"alumni\", \"graduation_year\": 2025, \"thesis_title\": \"Artificial Intelligence & Human-Computer Interaction: The development and deployment of emotionally intelligent, LLM-augmented conversational agent software, utilising generative AI to improve pedagogical and educational management processes\", \"topic_zh\": \"\u60c5\u611f\u667a\u80fd LLM \u5bf9\u8bdd\u4ee3\u7406\u7528\u4e8e\u6559\u5b66\u4e0e\u6559\u80b2\u7ba1\u7406\", \"url\": \"https://bura.brunel.ac.uk/handle/2438/32953\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"role\": \"\u7b2c\u4e8c\u5bfc\u5e08\uff08\u4e3b\u5bfc A. Money\uff09\"}, {\"name\": \"Nikolaos Droutsas\", \"status\": \"alumni\", \"graduation_year\": 2026, \"thesis_title\": \"A novel approach to automating context-driven alternative text generation through purposeful games\", \"topic_zh\": \"\u901a\u8fc7\u76ee\u7684\u6027\u6e38\u620f\u4f17\u5305\u751f\u6210\u60c5\u5883\u5316\u56fe\u7247\u66ff\u4ee3\u6587\u672c\uff08\u65e0\u969c\u788d\uff09\", \"url\": \"https://bura.brunel.ac.uk/handle/2438/32758\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"role\": \"\u7b2c\u4e8c\u5bfc\u5e08\uff08\u4e3b\u5bfc F. Spyridonis\uff09\"}], \"total_estimate\": \"BURA \u53ef\u89c1\u5df2\u6bd5\u4e1a 4 \u4f4d\uff082025\u20132026\uff09\uff1b\u4e2a\u4eba\u7ad9\u79f0\u5728\u8bfb 1 \u4f4d\uff08AR 3D \u6e38\u620f\u5316\u73af\u5883\u5e94\u5bf9\u9605\u8bfb\u969c\u788d\uff0c\u9875\u9762\u53ef\u80fd\u8f83\u65e7\uff09\", \"student_pattern_zh\": \"AI+\u6e38\u620f\uff1a\u751f\u6210\u5f0f AI \u7f8e\u672f\u8d44\u4ea7\u3001\u4e25\u8083\u6e38\u620f\u8bad\u7ec3\u3001LLM \u5bf9\u8bdd\u4ee3\u7406\u3001\u65e0\u969c\u788d\u4f17\u5305\u6e38\u620f\uff1b\u6280\u672f\u6784\u5efa+\u7528\u6237\u7814\u7a76\u7684\u8ba1\u7b97\u578b\u7814\u7a76\u3002\", \"design_background_ok_zh\": \"\u6240\u5728\u4e3a Brunel Design School \u6570\u5b57\u5a92\u4f53\u65b9\u5411\uff0c\u4f46\u5df2\u77e5\u5b66\u751f\u8bfe\u9898\u504f\u8ba1\u7b97\u673a/AI\uff1b\u65e0\u660e\u786e\u827a\u672f\u80cc\u666f\u5b66\u751f\u8bc1\u636e\u3002\", \"chinese_students_zh\": \"\u672a\u53d1\u73b0\u4e2d\u56fd\u5b66\u751f\u6216 CSC \u8bb0\u5f55\u3002\", \"implication_zh\": \"\u4ed6\u4e0e Mariza Dima \u5408\u4f5c AHRC \u6df7\u5408\u73b0\u5b9e\u9057\u4ea7\u8868\u6f14\u9879\u76ee\uff08Acting on the Edge / \u53bb\u6b96\u6c11\u5316\u9057\u4ea7\uff09\uff0c\u5e76\u5199\u8fc7 XR \u4e25\u8083\u6e38\u620f\u7528\u4e8e\u865a\u62df\u535a\u7269\u9986\u3002\u9002\u5408\u4f5c\u4e3a Dima \u7684\u6280\u672f\u526f\u5bfc\u5e08\uff1a\u7528\u6237\u53ef\u63d0\u51fa\u2018AI/\u624b\u52bf\u9a71\u52a8\u7684 XR \u535a\u7269\u9986\u53d9\u4e8b\u4f53\u9a8c\u2019\u3002\u5355\u72ec\u7533\u8bf7\u65f6\u9700\u5f3a\u8c03\u6280\u672f\u5b9e\u73b0\u80fd\u529b\uff08Unity/Three.js/MediaPipe\uff09\u3002\", \"sources\": [\"https://bura.brunel.ac.uk/handle/2438/30775\", \"https://bura.brunel.ac.uk/handle/2438/33439\", \"https://bura.brunel.ac.uk/handle/2438/32953\", \"https://bura.brunel.ac.uk/handle/2438/32758\", \"https://damondzad.com/teaching/\", \"https://bura.brunel.ac.uk/browse?type=author&value=Daylamani-Zad%2C+D\"], \"searched\": [\"Brunel \u4e2a\u4eba\u9875\u4e0e PhD supervision \u9875\", \"\u4e2a\u4eba\u7f51\u7ad9 damondzad.com\", \"BURA advisor \u5b57\u6bb5\uff08\u7ecf\u641c\u7d22\uff09\"]}, \"title_zh\": \"\u535a\u58eb\uff0c\u6570\u5b57\u5a92\u4f53\u9ad8\u7ea7\u8bb2\u5e08\uff08\u521b\u610f\u8ba1\u7b97\u2014\u2014AI \u4e0e\u6e38\u620f\uff09\uff1b\u5e03\u9c81\u5185\u5c14\u8bbe\u8ba1\u5b66\u9662\u6559\u5b66\u4e3b\u4efb\uff1b\u521b\u610f\u8ba1\u7b97\u7814\u7a76\u7ec4\u8d1f\u8d23\u4eba\", \"unit_zh\": \"\u6570\u5b57\u5a92\u4f53\uff0c\u5e03\u9c81\u5185\u5c14\u8bbe\u8ba1\u5b66\u9662\uff0c\u5de5\u7a0b\u3001\u8bbe\u8ba1\u4e0e\u81ea\u7136\u79d1\u5b66\u5b66\u9662\", \"evidence_projects_funding_zh\": \"\u521b\u610f\u8ba1\u7b97\u7814\u7a76\u7ec4\u8d1f\u8d23\u4eba\uff1b\u201c\u9762\u5411\u793e\u4f1a\u5f71\u54cd\u7684\u6df7\u5408\u73b0\u5b9e\u201d\uff08mxr4impact.com\uff09\u4e0e\u201c\u751f\u6d3b\u3001\u5065\u5eb7\u4e0e\u65e0\u969c\u788d\u6e38\u620f\u201d\u9879\u76ee\uff1b\u5b98\u65b9\u9875\u8bbe\u535a\u58eb\u6307\u5bfc\u680f\u76ee\u3002\", \"email_hook_zh\": \"Your work with Dr Dima on real-time MR heritage performance and on AI tools in MR pipelines connects to how I turn 3D scans of artefacts into interactive particle experiences.\uff08\u60a8\u4e0e Dima \u535a\u58eb\u5408\u4f5c\u7684\u5b9e\u65f6 MR \u9057\u4ea7\u8868\u6f14\u53ca MR \u6d41\u7a0b\u4e2d\u7684 AI \u5de5\u5177\u7814\u7a76\uff0c\u4e0e\u6211\u5c06\u6587\u7269\u4e09\u7ef4\u626b\u63cf\u8f6c\u5316\u4e3a\u4ea4\u4e92\u7c92\u5b50\u4f53\u9a8c\u7684\u505a\u6cd5\u76f8\u901a\u3002\uff09\", \"csc_status_zh\": \"\u6d3b\u8dc3\"}, {\"name\": \"Anastasia Bezerianos\", \"school_en\": \"Universit\u00e9 Paris-Saclay (former Paris-Sud)\", \"school_zh\": \"\u5df4\u9ece\u8428\u514b\u96f7\u5927\u5b66\uff08\u539f\u5df4\u9ece\u5357\u5341\u4e00\u5927\u5b66\uff09\", \"country\": \"\", \"title\": \"Full Professor (Professeure des universit\u00e9s); co-head of CS department, Polytech Paris-Saclay\", \"unit\": \"LISN (Laboratoire Interdisciplinaire des Sciences du Num\u00e9rique), IaH department, ILDA team (Inria/CNRS/Universit\u00e9 Paris-Saclay)\", \"homepage\": \"https://perso.lisn.upsaclay.fr/anab/\", \"email\": \"anastasia.bezerianos@universite-paris-saclay.fr\", \"relevance\": 6, \"claim\": \"Bezerianos \u662f\u5df4\u9ece\u8428\u514b\u96f7 LISN \u7684 HCI/\u53ef\u89c6\u5316\u6b63\u6559\u6388\uff08\u6301 HDR\uff09\uff0c\u7814\u7a76\u5927\u5c4f\u3001\u6c89\u6d78\u5f0f\u4e0e AR \u73af\u5883\u4e0b\u7684\u4ea4\u4e92\u4e0e\u611f\u77e5\uff0c\u53ef\u5728 Mackay/Bourdot \u4e4b\u5916\u4e3a\u7528\u6237\u63d0\u4f9b'\u6c89\u6d78\u5c55\u793a\u7a7a\u95f4\u4e2d\u7684\u611f\u77e5\u4e0e\u4ea4\u4e92\u8bc4\u4f30'\u65b9\u5411\u3002\", \"evidence_homepage\": \"https://perso.lisn.upsaclay.fr/anab/\", \"evidence_papers\": [{\"title\": \"Perception of Visual Variables on Virtual Wall-Sized Tiled Displays in Immersive Environments\", \"year\": 2025, \"venue\": \"IEEE TVCG 31(5)\", \"url\": \"https://ilda.saclay.inria.fr/publications.html\", \"link_to_user\": \"\u6c89\u6d78\u73af\u5883\u4e2d\u89c6\u89c9\u53d8\u91cf\u611f\u77e5 \u2192 \u7c92\u5b50\u4eae\u5ea6/\u5bc6\u5ea6\u4f5c\u4e3a'\u53d9\u4e8b\u7167\u660e'\u53d8\u91cf\u7684\u611f\u77e5\u5b9e\u9a8c\u8bbe\u8ba1\", \"title_zh\": \"\u6c89\u6d78\u5f0f\u73af\u5883\u4e2d\u865a\u62df\u5899\u9762\u5c3a\u5bf8\u62fc\u63a5\u663e\u793a\u5c4f\u4e0a\u89c6\u89c9\u53d8\u91cf\u7684\u611f\u77e5\"}, {\"title\": \"Shared, Replicated, or Separated? A Comparative Study of Virtual Workspace Configurations for Collaborative Hands-On Learning\", \"year\": 2025, \"venue\": \"IEEE ISMAR 2025\", \"url\": \"https://inria.hal.science/hal-05193514v1\", \"link_to_user\": \"VR \u534f\u4f5c\u52a8\u624b\u5b66\u4e60\u7684\u7a7a\u95f4\u914d\u7f6e\u5bf9\u6bd4 \u2192 \u535a\u7269\u9986\u591a\u4eba\u624b\u52bf\u5c55\u9879\u7684\u5e03\u5c40\u95ee\u9898\", \"title_zh\": \"\u5171\u4eab\u3001\u590d\u5236\u8fd8\u662f\u5206\u79bb\uff1f\u9762\u5411\u534f\u4f5c\u5f0f\u52a8\u624b\u5b66\u4e60\u7684\u865a\u62df\u5de5\u4f5c\u7a7a\u95f4\u914d\u7f6e\u6bd4\u8f83\u7814\u7a76\"}, {\"title\": \"Personal+Context navigation: Combining AR and shared displays in network path-following\", \"year\": 2020, \"venue\": \"Graphics Interface 2020\", \"url\": \"https://hal-centralesupelec.archives-ouvertes.fr/hal-02860063v1\", \"link_to_user\": \"AR + \u516c\u5171\u5927\u5c4f\u7ed3\u5408 \u2192 \u5c55\u5385\u5927\u5c4f\u4e0e\u4e2a\u4eba\u624b\u52bf\u4ea4\u4e92\u7684\u6df7\u5408\u65b9\u6848\", \"title_zh\": \"\u4e2a\u4eba+\u60c5\u5883\u5bfc\u822a\uff1a\u5728\u7f51\u7edc\u8def\u5f84\u8ffd\u8e2a\u4e2d\u7ed3\u5408 AR \u4e0e\u5171\u4eab\u663e\u793a\u5c4f\"}], \"evidence_projects_funding\": \"\u4e3b\u9875\u65b0\u95fb\uff1a2024-11 \u83b7\u4e24\u9879 ANR \u9879\u76ee CoMixS\u3001tVISt\uff1bANR ICARE\uff08\u6c89\u6d78\u5f0f\u534f\u4f5c\u5b66\u4e60\uff0c\u4e0e Prouzeau \u5408\u4f5c\uff09\u53c2\u4e0e\u8005\uff1b\u6307\u5bfc\u591a\u540d\u535a\u58eb\uff08Mehdi Chakhchoukh\u3001Rapha\u00ebl James 2024 \u6bd5\u4e1a\uff09\u3002HDR \u5df2\u83b7\u5f97\uff08\u4e3b\u9875 PDF\uff09\u3002\", \"fit_to_user\": \"\u5979\u6559\u6388 M1/M2 'Mixed Reality and Tangible Interaction' \u8bfe\u7a0b\uff0c\u7814\u7a76\u843d\u5728 HCI \u8bc4\u4f30\u65b9\u6cd5 + \u6c89\u6d78/AR \u663e\u793a\uff1b\u80fd\u5e2e\u7528\u6237\u628a Stone Reveal \u4ece\u4f5c\u54c1\u8f6c\u6210\u6709\u5bf9\u7167\u7ec4\u7684\u611f\u77e5/\u4f53\u9a8c\u5b9e\u9a8c\u3002\", \"counterargument_risk\": \"\u6838\u5fc3\u662f\u4fe1\u606f\u53ef\u89c6\u5316\u4e0e\u6570\u636e\u5206\u6790\uff0c\u4e0d\u505a\u6587\u5316\u9057\u4ea7\u6216\u7167\u660e\uff1b\u5bfc\u5e08\u504f\u597d\u8ba1\u7b97\u673a\u80cc\u666f\u5b66\u751f\uff0c\u8bbe\u8ba1\u80cc\u666f\u9700\u9760\u539f\u578b\u4e0e\u5b9e\u9a8c\u8ba1\u5212\u8bf4\u670d\u3002LISN \u535a\u58eb\u901a\u5e38\u9700 ED STIC \u5408\u540c\u6216 CSC\u3002\", \"email_hook\": \"Your TVCG 2025 study on how visual variables are perceived on virtual wall-sized displays is exactly the kind of evaluation my particle-based heritage displays still lack.\", \"sources\": [\"https://perso.lisn.upsaclay.fr/anab/\", \"https://www.lisn.upsaclay.fr/membres/bezerianos-anastasia/?lang=en\", \"https://scholar.google.com/citations?hl=en&user=975a_nYAAAAJ\", \"https://orcid.org/0000-0002-7142-2548\", \"https://perso.lisn.upsaclay.fr/anab/Anastasia-HDR.pdf\", \"https://ilda.saclay.inria.fr/publications.html\"], \"verified\": true, \"csc_note\": \"\u8f93\u5165\u663e\u793a\u8be5\u6821 CSC \u7ebf status=active\uff1b\u53ef\u8d70\u56fd\u5bb6\u516c\u6d3e\uff08\u8054\u5408\u57f9\u517b/\u653b\u8bfb\u535a\u58eb\uff09+ \u5b66\u6821/\u5bfc\u5e08\u63a5\u6536\u51fd\u8def\u7ebf\uff0c\u5177\u4f53\u540d\u989d\u4e0e\u622a\u6b62\u9700\u5728 CSC \u5b98\u7f51\u4e0e\u5b66\u6821\u56fd\u9645\u5904\u6838\u5b9e\u3002\", \"matched_keywords\": [\"HCI\", \"AR/VR\", \"immersive displays\", \"visualization\", \"evaluation\"], \"csc_status\": \"active\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"anastasia.bezerianos@universite-paris-saclay.fr\", \"subject\": \"PhD enquiry (CSC 2027): perception and interaction in immersive heritage displays\", \"body\": \"Dear Professor Bezerianos,\\n\\nYour TVCG 2025 study on the perception of visual variables on virtual wall-sized displays, and your ISMAR 2025 comparison of workspace configurations for collaborative hands-on learning, address exactly the evaluation my heritage installations still lack. I direct a teaching and research office for digital intangible cultural heritage at Quanzhou Huaguang College in China, and I am preparing a PhD application for September 2027.\\n\\nSince November 2025 I have led that office, teaching 3D character design and leading a VR collaborative lighting design project (JAT251371). Before that, as a lighting hardware product manager, I ran 9 product series at OSRAM/LEDVANCE (~100 SKUs, ~US$8M sales), including light-distribution analysis for Abu Dhabi's Zayed airport project, and led user research at LEEDARSON for smart-lighting lines selling over US$30M. I know how light is perceived and tested with real users.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as GPU particle clouds in Three.js, with MediaPipe hand tracking in the browser, so visitors brush away the \\\"dust\\\" with a fingertip and hold their palms together to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven particle displays and responsive lighting shape attention and understanding in museum settings, treating brightness, density and motion of light as visua");